import Button from "@mui/material/Button";
import Stack from "@mui/material/Stack";
import QuackNet from "./QuackNet";
import {styled} from '@mui/material/styles'


const BootstrapButton = styled(Button)({
  boxShadow: 'none',
  textTransform: 'none',
  fontSize: 16,
  color: '#061213',
  fontWeight: 'bold',
  padding: '6px 12px',
  lineHeight: 1.5,
  fontFamily: [
    'Poppins'
  ]
});

const FilledButton = styled(Button)({
  boxShadow: 'none',
  textTransform: 'none',
  fontSize: 16,
  padding: '6px 12px',
  border: '1px solid',
  lineHeight: 1.5,
  backgroundColor: '#0063cc',
  borderColor: '#0063cc',
  fontFamily: [
    '-apple-system',
    'BlinkMacSystemFont',
    '"Segoe UI"',
    'Roboto',
    '"Helvetica Neue"',
    'Arial',
    'sans-serif',
    '"Apple Color Emoji"',
    '"Segoe UI Emoji"',
    '"Segoe UI Symbol"',
  ].join(','),
  '&:hover': {
    backgroundColor: '#0069d9',
    borderColor: '#0062cc',
    boxShadow: 'none',
  },
  '&:active': {
    boxShadow: 'none',
    backgroundColor: '#0062cc',
    borderColor: '#005cbf',
  },
  '&:focus': {
    boxShadow: '0 0 0 0.2rem rgba(0,123,255,.5)',
  },
});

export default function NavigationBar() {
  return (
    <Stack direction="row" spacing={2} sx= {{ justifyContent: "space-evenly", alignItems: "flex-end" }}>
        <QuackNet />
      <BootstrapButton variant="text">Link Account</BootstrapButton>
      <BootstrapButton variant="text">Games</BootstrapButton>
      <BootstrapButton variant="text">About COMS</BootstrapButton>
      <Button variant="contained">Profile</Button>
    </Stack>
  );
}
